//! Signed, notification-only release checks. No executable is downloaded.
use anyhow::{anyhow, bail, ensure, Result};
use serde::Deserialize;
use std::{cmp::Ordering, collections::BTreeSet, time::Duration};
use url::Url;

// Production minisign public key generated by the owner with `minisign -G`.
// Signatures are checked against this exact key; the private key never ships.
pub const UPDATE_PUBLIC_KEY: &str = "RWTtGSFer94FZx9C2/b1vt6P5eS9t7J3n1xxO9yGSnrS2uTSreg0QgyG";
const RELEASES: &str = "https://github.com/cleisonsantos/dish/releases";
const DISCOVERY: &str = "https://api.github.com/repos/cleisonsantos/dish/releases?per_page=100";
const MANIFEST_LIMIT: u64 = 64 * 1024;

/// SemVer precedence, deliberately excluding build metadata from comparison.
#[derive(Debug, Clone, Eq, PartialEq)]
struct Version {
    core: [String; 3],
    pre: Vec<String>,
}
impl Version {
    fn parse(input: &str) -> Result<Self> {
        fn identifiers(value: &str, numeric_rule: bool) -> bool {
            value.split('.').all(|p| {
                !p.is_empty()
                    && p.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-')
                    && !(numeric_rule
                        && p.bytes().all(|b| b.is_ascii_digit())
                        && p.len() > 1
                        && p.starts_with('0'))
            })
        }
        let mut parts = input.split('+');
        let main = parts.next().unwrap_or_default();
        if let Some(build) = parts.next() {
            ensure!(identifiers(build, false), "invalid build metadata");
        }
        ensure!(parts.next().is_none(), "invalid version");
        let (core, pre) = main.split_once('-').unwrap_or((main, ""));
        let core: Vec<_> = core.split('.').map(str::to_owned).collect();
        ensure!(
            core.len() == 3
                && core.iter().all(|p| !p.is_empty()
                    && p.bytes().all(|b| b.is_ascii_digit())
                    && (p.len() == 1 || !p.starts_with('0'))),
            "invalid version core"
        );
        ensure!(
            !main.contains('-') || identifiers(pre, true),
            "invalid prerelease"
        );
        Ok(Self {
            core: core.try_into().unwrap(),
            pre: if pre.is_empty() {
                vec![]
            } else {
                pre.split('.').map(str::to_owned).collect()
            },
        })
    }
}
fn number_cmp(a: &str, b: &str) -> Ordering {
    a.len().cmp(&b.len()).then_with(|| a.cmp(b))
}
impl Ord for Version {
    fn cmp(&self, other: &Self) -> Ordering {
        for (a, b) in self.core.iter().zip(&other.core) {
            let order = number_cmp(a, b);
            if order != Ordering::Equal {
                return order;
            }
        }
        match (self.pre.is_empty(), other.pre.is_empty()) {
            (true, false) => return Ordering::Greater,
            (false, true) => return Ordering::Less,
            _ => {}
        }
        for (a, b) in self.pre.iter().zip(&other.pre) {
            let numeric = |s: &str| s.bytes().all(|b| b.is_ascii_digit());
            let order = match (numeric(a), numeric(b)) {
                (true, true) => number_cmp(a, b),
                (true, false) => Ordering::Less,
                (false, true) => Ordering::Greater,
                _ => a.cmp(b),
            };
            if order != Ordering::Equal {
                return order;
            }
        }
        self.pre.len().cmp(&other.pre.len())
    }
}
impl PartialOrd for Version {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

#[derive(Clone, Copy, Debug, serde::Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum UpdateChannel {
    Stable,
    Prerelease,
}
impl UpdateChannel {
    fn accepts(self, version: &Version) -> bool {
        self == Self::Prerelease || version.pre.is_empty()
    }
}

#[derive(Clone)]
pub struct Check {
    current: Version,
    current_label: String,
    channel: UpdateChannel,
    source: Option<String>,
    etag: Option<String>,
}
impl Check {
    /// Reserve the daily attempt before dispatch, including failures and future timestamps.
    pub fn automatic(preferences: &mut crate::preferences::Preferences, now: i64) -> Option<Self> {
        if !cfg!(all(target_os = "linux", target_arch = "x86_64"))
            || crate::version::is_local_build()
            || std::env::var("DISH_NO_UPDATE_CHECK").as_deref() == Ok("1")
        {
            return None;
        }
        let source = match std::env::var("DISH_UPDATE_URL") {
            Ok(source) => Some(source),
            Err(std::env::VarError::NotPresent) => None,
            Err(_) => {
                crate::logging::warn(format_args!(
                    "Dish: invalid update configuration; no notification"
                ));
                return None;
            }
        };
        let check = match Self::new(
            crate::version::release_version(),
            preferences.update_channel,
            source,
            preferences.last_update_etag.clone(),
        ) {
            Ok(check) => check,
            Err(_) => {
                crate::logging::warn(format_args!(
                    "Dish: invalid release version; no notification"
                ));
                return None;
            }
        };
        if !reserve_attempt(&mut preferences.last_update_check, now, daily_jitter()) {
            return None;
        }
        Some(check)
    }
    fn new(
        current: &str,
        channel: Option<UpdateChannel>,
        source: Option<String>,
        etag: Option<String>,
    ) -> Result<Self> {
        let version = Version::parse(current)?;
        let channel = channel.unwrap_or(if version.pre.is_empty() {
            UpdateChannel::Stable
        } else {
            UpdateChannel::Prerelease
        });
        Ok(Self {
            current: version,
            current_label: current.into(),
            channel,
            source,
            etag,
        })
    }
    pub fn run(self) -> Option<Outcome> {
        self.run_with_key(UPDATE_PUBLIC_KEY)
    }
    fn run_with_key(&self, key: &str) -> Option<Outcome> {
        match self.fetch(key) {
            Ok(outcome) => Some(outcome),
            Err(_) => {
                // Never log URLs, credentials, remote response bodies or untrusted metadata.
                crate::logging::warn(format_args!("Dish: update check failed; no notification"));
                None
            }
        }
    }
    fn fetch(&self, key: &str) -> Result<Outcome> {
        let http = Http::new(self.source.as_deref())?;
        self.fetch_from(key, &http, DISCOVERY)
    }
    fn fetch_from(&self, key: &str, http: &Http, discovery: &str) -> Result<Outcome> {
        let (manifest_url, signature_url, candidate, etag) = if let Some(source) = &self.source {
            (source.clone(), format!("{source}.minisig"), None, None)
        } else {
            let response = http.get(discovery, 2 * 1024 * 1024, self.etag.as_deref())?;
            if response.unchanged {
                return Ok(Outcome {
                    notification: None,
                    etag: self.etag.clone(),
                });
            }
            let releases: Vec<Release> = serde_json::from_slice(&response.bytes)?;
            let Some(release) = select_release(&releases, &self.current, self.channel) else {
                return Ok(Outcome {
                    notification: None,
                    etag: response.etag,
                });
            };
            let asset = |name: &str| -> Result<String> {
                let matches: Vec<_> = release.assets.iter().filter(|a| a.name == name).collect();
                ensure!(matches.len() == 1, "missing/duplicate manifest asset");
                Ok(matches[0].browser_download_url.clone())
            };
            (
                asset("latest.json")?,
                asset("latest.json.minisig")?,
                Some(release.clone()),
                response.etag,
            )
        };
        let bytes = http.get(&manifest_url, MANIFEST_LIMIT, None)?.bytes;
        let signature = http.get(&signature_url, 4096, None)?.bytes;
        // Authenticity gate: no JSON parsing of the manifest above this line.
        let (manifest, version) = Manifest::verify_parse(&bytes, &signature, key, http)?;
        if let Some(release) = candidate {
            ensure!(
                manifest.tag == release.tag_name,
                "manifest/release mismatch"
            );
            for asset in &manifest.assets {
                if !matches!(
                    asset.kind.as_str(),
                    "portable-linux-x86_64" | "debian-amd64"
                ) {
                    continue;
                }
                let matches: Vec<_> = release
                    .assets
                    .iter()
                    .filter(|a| a.name == asset.name)
                    .collect();
                ensure!(
                    matches.len() == 1
                        && matches[0].browser_download_url == asset.url
                        && matches[0].size == asset.size,
                    "missing/mismatched release asset"
                );
            }
        }
        let notification =
            (version > self.current && self.channel.accepts(&version)).then(|| Available {
                current: self.current_label.clone(),
                version: manifest.version,
                notes_url: manifest.notes_url,
            });
        Ok(Outcome { notification, etag })
    }
}

fn daily_jitter() -> i64 {
    use std::hash::{Hash, Hasher};
    let mut hash = std::collections::hash_map::DefaultHasher::new();
    std::env::var_os("XDG_CONFIG_HOME")
        .or_else(|| std::env::var_os("HOME"))
        .hash(&mut hash);
    (hash.finish() % (6 * 60 * 60 + 1)) as i64
}

fn reserve_attempt(last: &mut Option<i64>, now: i64, jitter: i64) -> bool {
    if last.is_some_and(|last| now.saturating_sub(last) < 24 * 60 * 60 + jitter) {
        return false;
    }
    *last = Some(now);
    true
}

pub struct Outcome {
    pub notification: Option<Available>,
    pub etag: Option<String>,
}
pub struct Available {
    current: String,
    version: String,
    notes_url: String,
}
impl Available {
    pub fn notification(self) -> crate::notifications::Notification {
        crate::notifications::Notification {
            id: format!("update-{}", self.version),
            title: format!("Dish {} → {} disponível", self.current, self.version),
            detail:
                "Uma nova versão do Dish está disponível. Veja o que mudou nas notas da release."
                    .into(),
            action_label: Some("Ver release".into()),
            action: Some(std::rc::Rc::new(move |_, _| {
                crate::platform::open_url(&self.notes_url)
            })),
        }
    }
}

#[derive(Clone, Deserialize)]
struct Release {
    tag_name: String,
    draft: bool,
    prerelease: bool,
    assets: Vec<ReleaseAsset>,
}
#[derive(Clone, Deserialize)]
struct ReleaseAsset {
    name: String,
    browser_download_url: String,
    size: u64,
}
fn select_release<'a>(
    releases: &'a [Release],
    current: &Version,
    channel: UpdateChannel,
) -> Option<&'a Release> {
    releases
        .iter()
        .filter(|r| !r.draft)
        .filter_map(|release| {
            let label = release.tag_name.strip_prefix('v')?;
            if label.contains('+') {
                return None;
            }
            let version = Version::parse(label).ok()?;
            (release.prerelease == !version.pre.is_empty()
                && channel.accepts(&version)
                && version > *current)
                .then_some((release, version))
        })
        .max_by(|a, b| a.1.cmp(&b.1))
        .map(|(release, _)| release)
}

#[derive(Deserialize)]
struct Manifest {
    schema: u32,
    version: String,
    tag: String,
    channel: UpdateChannel,
    published_at: String,
    notes_url: String,
    target: String,
    minimum_glibc: String,
    assets: Vec<Asset>,
}
#[derive(Deserialize)]
struct Asset {
    kind: String,
    name: String,
    sha256: String,
    size: u64,
    url: String,
}
impl Manifest {
    fn verify_parse(
        bytes: &[u8],
        signature: &[u8],
        key: &str,
        http: &Http,
    ) -> Result<(Self, Version)> {
        ensure!(
            bytes.len() <= MANIFEST_LIMIT as usize && signature.len() <= 4096,
            "response too large"
        );
        minisign_verify::PublicKey::from_base64(key)?.verify(
            bytes,
            &minisign_verify::Signature::decode(std::str::from_utf8(signature)?)?,
            false,
        )?;
        let manifest: Self = serde_json::from_slice(bytes)?;
        let version = manifest.validate(http)?;
        Ok((manifest, version))
    }
    fn validate(&self, http: &Http) -> Result<Version> {
        ensure!(
            self.schema == 1 && !self.version.contains('+'),
            "unsupported schema/version"
        );
        let version = Version::parse(&self.version)?;
        ensure!(self.tag == format!("v{}", self.version), "tag mismatch");
        ensure!(
            self.channel
                == if version.pre.is_empty() {
                    UpdateChannel::Stable
                } else {
                    UpdateChannel::Prerelease
                },
            "channel mismatch"
        );
        ensure!(
            self.notes_url == format!("{RELEASES}/tag/{}", self.tag),
            "invalid notes URL"
        );
        ensure!(
            self.target == "x86_64-unknown-linux-gnu",
            "unsupported target"
        );
        let date = chrono::DateTime::parse_from_rfc3339(&self.published_at)?;
        ensure!(
            date.offset().local_minus_utc() == 0,
            "timestamp must be UTC"
        );
        let glibc: Vec<_> = self.minimum_glibc.split('.').collect();
        ensure!(
            glibc.len() == 2
                && glibc
                    .iter()
                    .all(|p| !p.is_empty() && p.bytes().all(|b| b.is_ascii_digit())),
            "invalid glibc"
        );
        let (mut kinds, mut names, mut urls) = (BTreeSet::new(), BTreeSet::new(), BTreeSet::new());
        let mut recognized = false;
        for asset in &self.assets {
            ensure!(
                kinds.insert(&asset.kind) && names.insert(&asset.name) && urls.insert(&asset.url),
                "duplicate asset"
            );
            http.validate_url(&Url::parse(&asset.url)?)?;
            ensure!(
                asset.size > 0
                    && asset.sha256.len() == 64
                    && asset
                        .sha256
                        .bytes()
                        .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)),
                "invalid asset size/hash"
            );
            let expected = match asset.kind.as_str() {
                "portable-linux-x86_64" => format!("dish-{}-linux-x86_64.tar.gz", self.version),
                "debian-amd64" => format!("dish-pi_{}_amd64.deb", self.version),
                _ => continue,
            };
            recognized = true;
            ensure!(asset.name == expected, "asset name mismatch");
        }
        ensure!(recognized, "no supported Linux assets");
        Ok(version)
    }
}

struct Http {
    agent: ureq::Agent,
    origin: Option<Url>,
}
struct Response {
    bytes: Vec<u8>,
    etag: Option<String>,
    unchanged: bool,
}
impl Http {
    fn new(source: Option<&str>) -> Result<Self> {
        let origin = source.map(Url::parse).transpose()?;
        let config = ureq::Agent::config_builder()
            .max_redirects(0)
            .timeout_global(Some(Duration::from_secs(15)))
            .timeout_connect(Some(Duration::from_secs(5)))
            .timeout_resolve(Some(Duration::from_secs(5)))
            .build();
        let http = Self {
            agent: config.into(),
            origin,
        };
        if let Some(origin) = &http.origin {
            http.validate_url(origin)?;
        }
        Ok(http)
    }
    fn validate_url(&self, url: &Url) -> Result<()> {
        ensure!(
            url.username().is_empty() && url.password().is_none() && url.fragment().is_none(),
            "invalid URL"
        );
        let host = url.host_str().ok_or_else(|| anyhow!("missing host"))?;
        let loopback = host
            .trim_matches(['[', ']'])
            .parse::<std::net::IpAddr>()
            .is_ok_and(|ip| ip.is_loopback());
        if url.scheme() == "http" {
            ensure!(
                self.origin.is_some() && loopback,
                "HTTP only allowed on loopback with override"
            );
        } else {
            ensure!(url.scheme() == "https", "HTTPS required");
        }
        ensure!(
            [
                "api.github.com",
                "github.com",
                "release-assets.githubusercontent.com",
                "objects.githubusercontent.com"
            ]
            .contains(&host)
                || self
                    .origin
                    .as_ref()
                    .is_some_and(|origin| origin.host_str() == Some(host) || loopback),
            "host not allowed"
        );
        Ok(())
    }
    fn get(&self, input: &str, limit: u64, etag: Option<&str>) -> Result<Response> {
        let mut url = Url::parse(input)?;
        for redirects in 0..=5 {
            self.validate_url(&url)?;
            let mut request = self
                .agent
                .get(url.as_str())
                .header(
                    "User-Agent",
                    &format!("dish/{}", crate::version::release_version()),
                )
                .header("Accept", "application/vnd.github+json")
                .header("X-GitHub-Api-Version", "2022-11-28");
            if let Some(etag) = etag {
                request = request.header("If-None-Match", etag);
            }
            let mut response = request.call()?;
            let status = response.status().as_u16();
            if matches!(status, 301 | 302 | 303 | 307 | 308) {
                ensure!(redirects < 5, "too many redirects");
                let location = response
                    .headers()
                    .get("location")
                    .ok_or_else(|| anyhow!("missing redirect"))?
                    .to_str()?;
                let next = url.join(location)?;
                ensure!(
                    url.scheme() != "https" || next.scheme() == "https",
                    "TLS downgrade"
                );
                url = next;
                continue;
            }
            ensure!(status == 200 || status == 304, "unexpected HTTP status");
            return Ok(Response {
                etag: response
                    .headers()
                    .get("etag")
                    .and_then(|h| h.to_str().ok())
                    .map(str::to_owned),
                unchanged: status == 304,
                bytes: if status == 304 {
                    vec![]
                } else {
                    response
                        .body_mut()
                        .with_config()
                        .limit(limit)
                        .read_to_vec()?
                },
            });
        }
        bail!("redirect limit")
    }
}

